def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp_last = history[-1][1]
    my_last = history[-1][0]
    if n >= 2:
        opp_prev = history[-2][1]
        my_prev = history[-2][0]
        if opp_last == 'D' and opp_prev == 'D':
            return 'D'
        if my_last == 'D' and opp_last == 'D':
            return 'D'
        if opp_last == 'D' and my_last == 'C':
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        if opp_last == 'C' and my_last == 'D':
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if opp_last == 'D':
            return 'D'
        if n >= 5:
            last5 = history[-5:]
            opp_defects = sum(1 for (m, o) in last5 if o == 'D')
            if opp_defects >= 3:
                return 'D'
        if n >= 10:
            last10 = history[-10:]
            opp_defects = sum(1 for (m, o) in last10 if o == 'D')
            my_defects = sum(1 for (m, o) in last10 if m == 'D')
            if opp_defects == 0:
                return 'C'
            if my_defects > opp_defects + 1:
                return 'C'
        return 'C'
    return 'C'

